import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"温公易说 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"温公易说 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"zh/classics/wengong/012.md","filePath":"zh/classics/wengong/012.md"}'),n={name:"zh/classics/wengong/012.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><h3 id="彖曰-泰-小往大来-吉亨-则是天地交而万物通也-上下交而其志同也。内阳而外阴-内健而外顺-内君子而外小人。君子道长-小人道消也。" tabindex="-1">彖曰：泰，小往大来，吉亨，则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人。君子道长，小人道消也。 <a class="header-anchor" href="#彖曰-泰-小往大来-吉亨-则是天地交而万物通也-上下交而其志同也。内阳而外阴-内健而外顺-内君子而外小人。君子道长-小人道消也。" aria-label="Permalink to “彖曰：泰，小往大来，吉亨，则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人。君子道长，小人道消也。”">​</a></h3><h3 id="象曰-天地交-泰。后以财成天地之道-辅相天地之宜-以左右民。" tabindex="-1">象曰：天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。 <a class="header-anchor" href="#象曰-天地交-泰。后以财成天地之道-辅相天地之宜-以左右民。" aria-label="Permalink to “象曰：天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。”">​</a></h3><p>象曰后以财成天地之道，辅相天地之宜，何也？夫万物生之者天也，成之者地也。天地能生成之而不能治也，君者所以治人而成天地之功也。非后则天地何以得通乎？太曰：天之所贵曰生，物之所尊曰人，人之大伦曰治。治之所因曰辟，崇天普地，分群偶物，使不失其统者，莫若乎辟。天辟乎上，地辟乎下，君辟乎中，此之谓也。</p><h3 id="初九-拔茅茹-以其彚-征吉-象曰-拔茅征吉-志在外也。" tabindex="-1">初九：拔茅茹，以其彚，征吉 象曰：拔茅征吉，志在外也。 <a class="header-anchor" href="#初九-拔茅茹-以其彚-征吉-象曰-拔茅征吉-志在外也。" aria-label="Permalink to “初九：拔茅茹，以其彚，征吉 象曰：拔茅征吉，志在外也。”">​</a></h3><h3 id="九二-包荒-用冯河-不遐遗-朋亡得-尚于中行-象曰-包荒得尚于中行-以光大也。" tabindex="-1">九二：包荒，用冯河，不遐遗，朋亡得，尚于中行 象曰：包荒得尚于中行，以光大也。 <a class="header-anchor" href="#九二-包荒-用冯河-不遐遗-朋亡得-尚于中行-象曰-包荒得尚于中行-以光大也。" aria-label="Permalink to “九二：包荒，用冯河，不遐遗，朋亡得，尚于中行 象曰：包荒得尚于中行，以光大也。”">​</a></h3><h3 id="九三-无平不陂-无往不复-艰贞无咎-勿恤其孚-于食有福-象曰-无往不复-天地际也。" tabindex="-1">九三：无平不陂，无往不复，艰贞无咎，勿恤其孚，于食有福 象曰：无往不复，天地际也。 <a class="header-anchor" href="#九三-无平不陂-无往不复-艰贞无咎-勿恤其孚-于食有福-象曰-无往不复-天地际也。" aria-label="Permalink to “九三：无平不陂，无往不复，艰贞无咎，勿恤其孚，于食有福 象曰：无往不复，天地际也。”">​</a></h3><p>物极则反，天地之常也。是故治者乱之原也，通者塞之端也。三居天地之际，刚德将退，柔德将进，故曰无平不陂，无往不复。君子于是时也，何为而可哉？必也执节守道而独行其志乎？故曰艰贞无咎，君子之道也。患志之不笃，不患人之不信。譬如农夫，是穮是蔉，虽有饥馑，必有丰年。故勿恤其孚，君子之干禄也。修其性，俟其命而已矣，然后能永享安荣也。故曰于食有福。《诗》云：恺悌君子，求福不回，此之谓也。</p><h3 id="六四-翩翩-不富-以其邻-不戒以孚-象曰-翩翩不富-皆失实也。不戒以孚-中心愿也。" tabindex="-1">六四：翩翩，不富，以其邻，不戒以孚 象曰：翩翩不富，皆失实也。不戒以孚，中心愿也。 <a class="header-anchor" href="#六四-翩翩-不富-以其邻-不戒以孚-象曰-翩翩不富-皆失实也。不戒以孚-中心愿也。" aria-label="Permalink to “六四：翩翩，不富，以其邻，不戒以孚 象曰：翩翩不富，皆失实也。不戒以孚，中心愿也。”">​</a></h3><h3 id="六五-帝乙归妹-以祉-元吉-象曰-以祉元吉-中以行愿也。" tabindex="-1">六五：帝乙归妹，以祉，元吉 象曰：以祉元吉，中以行愿也。 <a class="header-anchor" href="#六五-帝乙归妹-以祉-元吉-象曰-以祉元吉-中以行愿也。" aria-label="Permalink to “六五：帝乙归妹，以祉，元吉 象曰：以祉元吉，中以行愿也。”">​</a></h3><h3 id="上六-城复于隍-勿用师-自邑告命-贞吝-象曰-城复于隍-其命乱也。" tabindex="-1">上六：城复于隍，勿用师，自邑告命，贞吝 象曰：城复于隍，其命乱也。 <a class="header-anchor" href="#上六-城复于隍-勿用师-自邑告命-贞吝-象曰-城复于隍-其命乱也。" aria-label="Permalink to “上六：城复于隍，勿用师，自邑告命，贞吝 象曰：城复于隍，其命乱也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
